/**
 * StoryBoard Live — single-image scroll engine.
 *
 * Applies Storyboard Production Sheet rules to ONE confirmed Golden Master
 * image. No frame sequence is decoded. The visitor's native scroll drives a
 * cinematic transform (scale / pan / opacity / blur) across the 12-beat
 * timeline, HTML overlays reveal at their frame thresholds, the real theme
 * header reveals near the end, and a reversible golden handoff releases the
 * story to the live page.
 *
 * Respects prefers-reduced-motion by holding the golden frame statically.
 */
( function () {
	'use strict';

	function clamp( value, min, max ) {
		return Math.min( max, Math.max( min, value ) );
	}

	function lerp( from, to, t ) {
		return from + ( to - from ) * t;
	}

	// easeOutCubic keeps motion calm and premium, matching the production notes.
	function ease( t ) {
		return 1 - Math.pow( 1 - t, 3 );
	}

	function parseManifest( root ) {
		var node = root.querySelector( '.shseq-single__manifest' );
		if ( ! node ) {
			return null;
		}
		try {
			return JSON.parse( node.textContent );
		} catch ( error ) {
			return null;
		}
	}

	function frameToProgress( frame, total ) {
		if ( total <= 1 ) {
			return 0;
		}
		return clamp( ( frame - 1 ) / ( total - 1 ), 0, 1 );
	}

	function initInstance( root ) {
		var manifest = parseManifest( root );
		if ( ! manifest ) {
			return;
		}

		var reduced = window.matchMedia( '(prefers-reduced-motion: reduce)' );
		var stage = root.querySelector( '[data-shseq-stage]' );
		var image = root.querySelector( '[data-shseq-image]' );
		var progressBar = root.querySelector( '[data-shseq-progress]' );
		var overlays = Array.prototype.slice.call( root.querySelectorAll( '[data-shseq-overlay]' ) );

		if ( ! stage || ! image ) {
			return;
		}

		var total = manifest.totalFrames || 120;
		var referenceFrame = manifest.referenceFrame || 70;
		var goldenFrame = manifest.goldenFrame || total;
		var camera = manifest.camera || {};
		var header = manifest.siteHeader || {};
		var handoff = manifest.handoff || {};

		// Camera entry motion: from a slightly pushed-in, softened opening to the
		// locked master framing at the reference frame; then fully static
		// (LOCK 070 -> 120) exactly as the production red lines require.
		var referenceProgress = frameToProgress( referenceFrame, total );
		var fromScale = typeof camera.fromScale === 'number' ? camera.fromScale : 1.12;
		var fromX = typeof camera.fromX === 'number' ? camera.fromX : 0;
		var fromY = typeof camera.fromY === 'number' ? camera.fromY : 4;
		var fromBlur = typeof camera.fromBlur === 'number' ? camera.fromBlur : 6;
		var fromOpacity = typeof camera.fromOpacity === 'number' ? camera.fromOpacity : 0.55;

		function applyStatic() {
			image.style.transform = 'scale(1) translate3d(0,0,0)';
			image.style.filter = 'none';
			image.style.opacity = '1';
			overlays.forEach( function ( el ) {
				el.classList.add( 'is-visible' );
				el.style.opacity = '';
				el.style.transform = '';
			} );
			root.classList.add( 'is-static' );
			if ( progressBar ) {
				progressBar.style.transform = 'scaleX(1)';
			}
		}

		if ( reduced.matches ) {
			applyStatic();
			return;
		}

		function updateOverlays( progress ) {
			overlays.forEach( function ( el ) {
				var revealFrame = parseInt( el.getAttribute( 'data-shseq-reveal-frame' ), 10 );
				if ( isNaN( revealFrame ) ) {
					revealFrame = goldenFrame;
				}
				var revealProgress = frameToProgress( revealFrame, total );
				var span = 0.05; // reveal window in progress units
				var local = clamp( ( progress - revealProgress ) / span, 0, 1 );
				var eased = ease( local );
				el.style.opacity = String( eased );
				el.style.transform = 'translate3d(0,' + lerp( 14, 0, eased ).toFixed( 2 ) + 'px,0)';
				if ( eased > 0.99 ) {
					el.classList.add( 'is-visible' );
				} else {
					el.classList.remove( 'is-visible' );
				}
				// Interactive elements stay inert until nearly revealed.
				el.style.pointerEvents = eased > 0.9 ? 'auto' : 'none';
			} );
		}

		function updateHeader( progress ) {
			var startFrame = header.startFrame || Math.round( total * 0.9 );
			var completeFrame = header.completeFrame || total;
			var startP = frameToProgress( startFrame, total );
			var endP = frameToProgress( completeFrame, total );
			var local = endP > startP ? clamp( ( progress - startP ) / ( endP - startP ), 0, 1 ) : ( progress >= startP ? 1 : 0 );
			root.style.setProperty( '--shseq-header-reveal', ease( local ).toFixed( 3 ) );
			if ( local > 0.6 ) {
				root.classList.add( 'is-header-interactive' );
			} else {
				root.classList.remove( 'is-header-interactive' );
			}
		}

		function updateHandoff( progress ) {
			var startProgress = typeof handoff.startProgress === 'number' ? handoff.startProgress : 0.995;
			var reverseThreshold = typeof handoff.reverseThreshold === 'number' ? handoff.reverseThreshold : 0.985;
			if ( progress >= startProgress ) {
				root.classList.add( 'is-handoff' );
			} else if ( progress <= reverseThreshold ) {
				root.classList.remove( 'is-handoff' );
			}
		}

		function render() {
			var rect = root.getBoundingClientRect();
			var viewport = window.innerHeight || document.documentElement.clientHeight;
			// Progress across the pinned scroll space.
			var scrollable = root.offsetHeight - viewport;
			var scrolled = clamp( -rect.top, 0, scrollable > 0 ? scrollable : 1 );
			var progress = scrollable > 0 ? clamp( scrolled / scrollable, 0, 1 ) : 0;

			// Camera transform: interpolate only up to the reference frame, then LOCK.
			var camT = progress <= referenceProgress && referenceProgress > 0
				? ease( progress / referenceProgress )
				: 1;

			var scale = lerp( fromScale, 1, camT );
			var tx = lerp( fromX, 0, camT );
			var ty = lerp( fromY, 0, camT );
			var blur = lerp( fromBlur, 0, camT );
			var opacity = lerp( fromOpacity, 1, camT );

			image.style.transform = 'scale(' + scale.toFixed( 4 ) + ') translate3d(' + tx.toFixed( 2 ) + 'px,' + ty.toFixed( 2 ) + 'px,0)';
			image.style.filter = blur > 0.05 ? 'blur(' + blur.toFixed( 2 ) + 'px)' : 'none';
			image.style.opacity = opacity.toFixed( 3 );

			updateOverlays( progress );
			updateHeader( progress );
			updateHandoff( progress );

			if ( progressBar ) {
				progressBar.style.transform = 'scaleX(' + progress.toFixed( 4 ) + ')';
			}
		}

		var ticking = false;
		function onScroll() {
			if ( ticking ) {
				return;
			}
			ticking = true;
			window.requestAnimationFrame( function () {
				render();
				ticking = false;
			} );
		}

		function onMotionChange( event ) {
			if ( event.matches ) {
				window.removeEventListener( 'scroll', onScroll );
				window.removeEventListener( 'resize', onScroll );
				applyStatic();
			}
		}

		root.classList.add( 'is-live' );
		window.addEventListener( 'scroll', onScroll, { passive: true } );
		window.addEventListener( 'resize', onScroll, { passive: true } );
		if ( typeof reduced.addEventListener === 'function' ) {
			reduced.addEventListener( 'change', onMotionChange );
		} else if ( typeof reduced.addListener === 'function' ) {
			reduced.addListener( onMotionChange );
		}
		render();
	}

	function boot() {
		var roots = document.querySelectorAll( '[data-shseq-single]' );
		Array.prototype.forEach.call( roots, initInstance );
	}

	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', boot );
	} else {
		boot();
	}
}() );
